/* @lc app=leetcode id=1001 lang=kotlin */ class Solution { fun gridIllumination(n: Int, lamps: Array<IntArray>, queries: Array<IntArray>): IntArray = HashSet(lamps.map { it[0] to it[1] }).let { ls -> List(4) { HashMap<Int, Int>() }.let { m -> ls.forEach { (r, c) -> listOf(r, c, r - c, r + c).forEachIndexed { k, v -> m[k].merge(v, 1) { a, b -> a + b } } }.let { queries.map { (r, c) -> (if ((0..3).any { k -> (m[k][listOf(r, c, r - c, r + c)[k]] ?: 0) > 0 }) 1 else 0).also { (-1..1).forEach { dr -> (-1..1).forEach { dc -> if (ls.remove(r + dr to c + dc)) listOf(r + dr, c + dc, r + dr - c - dc, r + dr + c + dc).forEachIndexed { k, v -> m[k].merge(v, -1) { a, b -> a + b } } } } } }.toIntArray() } } } }